mapper.select:
SELECT a.conf_id
FROM bm_inspection_conf a
where a.cnof_name=#{cnofName,jdbcType=VARCHAR} and a.delete_flag = 0

    and conf_id != #{confId}

${dataScope}
limit 1

SELECT a.conf_id, a.cnof_name, a.grid_id, b.grid_name, a.keeper_name, a.creator, a.create_time, a.modifier,
    a.update_time, a.delete_flag, a.conf_status, a.data_time, a.is_assign
FROM bm_inspection_conf a LEFT JOIN bm_grid b ON a.grid_id = b.grid_id
 a.delete_flag = 0 AND a.tenant_id = #{tenantId} AND a.industry_code = #{industryCode}

    AND a.grid_id = #{gridId,jdbcType=VARCHAR}


    AND a.cnof_name LIKE CONCAT('%', #{cnofName}, '%')


    AND a.keeper_name LIKE CONCAT('%', #{keeperName}, '%')


    AND a.conf_status = #{confStatus}


    AND a.creator LIKE CONCAT('%', #{creator}, '%')


    AND a.modifier LIKE CONCAT('%', #{modifier}, '%')


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{createStartDate}


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{createEndDate}


    and DATE_FORMAT(a.update_time,'%Y-%m-%d') >= #{modifyStartDate}


    and DATE_FORMAT(a.update_time,'%Y-%m-%d') <= #{modifyEndDate}



    order by a.create_time DESC


    order by a.update_time DESC


    order by a.create_time ASC


    order by a.update_time ASC

SELECT a.task_id, a.conf_id, a.cnof_name as task_name, a.grid_id, a.keeper_name, a.start_time, a.end_time, a.inspection_time, a.create_time, a.task_status, a.conf_desc as task_desc, a.retroaction, DATE_FORMAT(a.create_time,'%Y-%m-%d') create_date, a.inspection_start_time, a.inspection_end_time, a.feedback_keeper_id, a.feedback_end, b.keeper_name feedbackKeeperName, c.grid_name gridName FROM bm_inspection_task a left join bm_gridkeeper b on a.feedback_keeper_id = b.keeper_id left join bm_grid c on a.grid_id = c.grid_id WHERE a.send_flag = 1
AND ((a.task_status = '1' and a.feedback_keeper_id = #{feedbackKeeperId,jdbcType=VARCHAR}) or a.task_status = '2')
AND a.task_status = #{taskStatus,jdbcType=VARCHAR}
AND a.feedback_keeper_id = #{feedbackKeeperId,jdbcType=VARCHAR}
${dataScope}
AND a.delete_flag = #{deleteFlag}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') <= #{endDate}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{createStartTime}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{createEndTime}
AND a.grid_id LIKE concat('%',#{gridId},'%')
AND a.cnof_name LIKE concat('%',#{taskName},'%')
AND FIND_IN_SET(#{keeperId,jdbcType=VARCHAR},a.keeper_id)
AND a.conf_id = #{confId,jdbcType=VARCHAR}
AND a.keeper_name LIKE concat('%',#{keeperName},'%')
AND a.feedback_end = #{feedbackEnd,jdbcType=VARCHAR}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{taskDistributionStartTime}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{taskDistributionEndTime}
AND b.keeper_name LIKE concat('%',#{feedbackKeeperName},'%')
order by DATE_FORMAT(a.create_time,'%Y-%m-%d')
desc
asc
order by a.inspection_start_time
desc
asc
,a.inspection_end_time
desc
asc
order by a.create_time
desc
asc
order by a.inspection_time
desc
asc
ORDER BY create_date DESC,a.inspection_start_time DESC,a.inspection_end_time DESC,DATE_FORMAT(a.create_time,'%Y-%m-%d') DESC

SELECT a.task_id, a.conf_id, a.cnof_name as task_name, a.grid_id, a.keeper_id, a.keeper_name, a.create_time, a.task_status, a.feedback_keeper_id, a.feedback_end, DATE_FORMAT(a.create_time,'%Y-%m-%d') create_date, a.inspection_start_time, a.inspection_end_time, c.grid_name gridName FROM bm_inspection_task a left join bm_grid c on a.grid_id = c.grid_id WHERE a.send_flag = 1 AND a.delete_flag = 0
AND a.create_time >= #{createStartTime} AND a.create_time <= #{createEndTime}
AND a.cnof_name LIKE concat('%',#{taskName},'%')
AND a.task_status = #{taskStatus}
AND a.grid_id = #{gridId}
${dataScope}
AND a.grid_id in
#{item}
ORDER BY create_date DESC,a.inspection_start_time DESC,a.inspection_end_time DESC

SELECT a.task_id, a.conf_id, a.cnof_name as task_name, a.grid_id, a.keeper_id, a.keeper_name, a.start_time, a.end_time, a.inspection_time, a.create_time, a.task_status, a.conf_desc as task_desc, a.retroaction, DATE_FORMAT(a.create_time,'%Y-%m-%d') create_date, a.inspection_start_time, a.inspection_end_time, a.feedback_keeper_id, a.feedback_end, b.keeper_name feedbackKeeperName, c.grid_name gridName FROM bm_inspection_task a left join bm_gridkeeper b on a.feedback_keeper_id = b.keeper_id left join bm_grid c on a.grid_id = c.grid_id WHERE a.send_flag = 1
AND a.task_status = #{taskStatus,jdbcType=VARCHAR}
AND a.feedback_keeper_id = #{feedbackKeeperId,jdbcType=VARCHAR}
${dataScope}
AND a.delete_flag = #{deleteFlag}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') <= #{endDate}
and a.create_time >= #{createStartTime}
and a.create_time <= #{createEndTime}
AND a.grid_id LIKE concat('%',#{gridId},'%')
AND a.cnof_name LIKE concat('%',#{taskName},'%')
AND FIND_IN_SET(#{keeperId,jdbcType=VARCHAR},a.keeper_id)
AND a.conf_id = #{confId,jdbcType=VARCHAR}
AND a.keeper_name LIKE concat('%',#{keeperName},'%')
AND a.feedback_end = #{feedbackEnd,jdbcType=VARCHAR}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{taskDistributionStartTime}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{taskDistributionEndTime}
AND b.keeper_name LIKE concat('%',#{feedbackKeeperName},'%')
AND a.grid_id in
#{item}
ORDER BY create_date DESC,a.inspection_start_time DESC,a.inspection_end_time DESC

SELECT
    a.keeper_id,
    a.task_id,
    a.conf_id,
    a.cnof_name as task_name,
    a.grid_id,
    a.grid_name,
    a.keeper_name,
    a.start_time,
    a.end_time,
    a.inspection_time,
    a.create_time,
    a.task_status,
    a.conf_desc as task_desc,
    a.retroaction,
    a.tenant_id,
    a.fj_id,
    a.voice_url,
    a.video_url,
    a.industry_code,
    a.app_ver_code,
    a.send_flag
FROM
bm_inspection_task a
inner join bm_grid bg on a.grid_id = bg.grid_id
WHERE a.send_flag = 1

    ${dataScope}


    AND a.delete_flag = #{deleteFlag}


    and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') >= #{startDate}


    and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') <= #{endDate}


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{createStartTime}


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{createEndTime}


    AND a.grid_id = #{gridId}


    AND a.cnof_name LIKE concat('%',#{taskName},'%')


    AND a.keeper_id = #{keeperId}


    AND a.task_status = #{taskStatus,jdbcType=VARCHAR}


    AND a.conf_id = #{confId,jdbcType=VARCHAR}


    AND a.keeper_name LIKE concat('%',#{keeperName},'%')


    AND bg.province_id = #{provinceId}


    AND bg.city_id = #{cityId}

select task_id,conf_id,task_status,create_time,send_flag
from bm_inspection_task
where conf_id = #{confId}

select conf_status,conf_id
from bm_inspection_conf
where conf_id = #{confId}

SELECT a.keeper_name, a.keeper_phone_number, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as is_line, b.AVATAR FROM bm_gridkeeper a LEFT JOIN sys_user b ON a.staff_id = b.USER_ID WHERE a.delete_flag = 0 AND b.DEL_FLAG = '0' and b.STATUS = '0'
AND a.keeper_id IN
#{item}
